import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/M-S-NL4.PyU7auYU.js";import{_ as r,o,c as n,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Abonné iOS NightLite","description":"","frontmatter":{"source_hash":"12ee29c8aa","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/nightlite.md","filePath":"fr/use/nightlite.md"}'),l={name:"fr/use/nightlite.md"};function p(c,e,u,d,h,m){return o(),n("div",null,[...e[0]||(e[0]=[s('<p>NightLite est un service d&#39;abonné léger, compatible Nightscout. C&#39;est une alternative plus simple à votre propre site Nightscout lorsque vous avez seulement besoin de partager votre glycémie avec des abonnés.</p><p>xDrip est le <strong>principal</strong> (il envoie vos données). L&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">application iOS NightLite</a> (un fork de Nightguard, par Richard Lander) est l&#39;<strong>abonné</strong> et affiche vos données sur iPhone, iPad, Apple Watch ou Mac.</p><div class="info custom-block"><p class="custom-block-title">Le saviez-vous ?</p><p>xDrip n&#39;envoie que les 12 dernières heures de glycémies (avec tendance et delta) et de traitements, actualisées à chaque nouvelle valeur (environ toutes les 5 minutes).</p></div><h3 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h3><ul><li>xDrip en version <a href="./../install/download.html#pre-release">nightly</a> récente (au minimum celle du <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.03.01" target="_blank" rel="noreferrer">1er mars 2026</a>).</li><li>Une URL NightLite pour votre compte. Elle contient votre clé de sécurité et c&#39;est la seule chose à saisir : xDrip génère à partir d&#39;elle le QR code destiné à l&#39;abonné.</li><li>Pour l&#39;abonné : un iPhone ou iPad (iOS 15+), une Apple Watch (watchOS 9.1+) ou un Mac (macOS 12 avec M1 ou plus récent) avec l&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">application NightLite</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>NightLite ne peut pas être utilisé lorsque xDrip fonctionne en tant qu&#39;<a href="./../install/nightscoutfollower.html">abonné Nightscout</a>. Il ne fonctionne que si xDrip est votre source de données principale.</p></div><h3 id="setup-the-master-xdrip" tabindex="-1">Configurer le principal (xDrip) <a class="header-anchor" href="#setup-the-master-xdrip" aria-label="Permalink to &quot;Configurer le principal (xDrip) {#setup-the-master-xdrip}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Chargement vers Cloud<br>   NightLite</p></div><p>Saisissez votre URL NightLite :</p><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard (généralement saisie en scannant le QR code du tableau de bord)<br>  This contains your security key - do not disclose it (contient votre clé de sécurité, ne la divulguez pas)</p></div><p>Activez ensuite l&#39;envoi :</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service (envoyer ou non au service distant)</p></div><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>L&#39;URL NightLite contient votre clé de sécurité. Toute personne qui la possède peut accéder à vos données : ne la partagez pas.</p></div><h3 id="connect-a-follower" tabindex="-1">Connecter un abonné <a class="header-anchor" href="#connect-a-follower" aria-label="Permalink to &quot;Connecter un abonné {#connect-a-follower}&quot;">​</a></h3><p>Une fois l&#39;envoi activé, xDrip peut afficher un QR code qui contient toute votre configuration. C&#39;est ce code que votre abonné scanne ; il n&#39;y a rien à saisir sur l&#39;appareil de l&#39;abonné.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher le code QR</p><p> Code-barres à scanner pour les abonnés afin de les configurer automatiquement</p></div><ol><li>Installez l&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">application NightLite</a> sur l&#39;appareil de l&#39;abonné.</li><li>Sur le téléphone principal, appuyez sur <strong>Afficher le code QR</strong>. xDrip affiche le QR code <code>NightLite configuration</code>.</li><li>Dans les préférences de l&#39;application NightLite, appuyez sur l&#39;icône de scan à côté du champ Nightscout URL et scannez le QR code sur l&#39;écran du téléphone principal.</li></ol><img src="'+a+'" style="zoom:33%;"><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Le service NightLite peut renvoyer des notifications à xDrip et peut arrêter l&#39;envoi à distance si nécessaire.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',21)])])}const x=r(l,[["render",p]]);export{_ as __pageData,x as default};
